package ai.qxvision.signal.features

import ai.qxvision.signal.domain.*
import kotlin.math.abs
import kotlin.math.max
import kotlin.math.min
import kotlin.math.sqrt

const val FEATURE_SCHEMA_VERSION = "qxvision.features.v1"

/** Technical features operate only on reconstructed geometry; no price is invented. */
class FeatureEngine {
    private fun range(c: ReconstructedCandle)=max(.0001f,c.totalRange)
    private fun signed(c: ReconstructedCandle)=when(c.direction){Direction.UP->1f;Direction.DOWN->-1f;else->0f}
    private fun clamp(v:Float)=v.coerceIn(0f,1f)

    fun state(candles: List<ReconstructedCandle>): MarketState {
        val usable=if(candles.lastOrNull()?.isComplete==false)candles.dropLast(1) else candles
        val src=if(usable.isEmpty())candles else usable
        val returns=src.zipWithNext().map{it.second.relativeClose-it.first.relativeClose}
        val median=src.map(::range).sorted().let{if(it.isEmpty())0f else it[it.size/2]}
        val short=src.takeLast(6).map{it.relativeClose}; val all=src.map{it.relativeClose}
        fun slope(v:List<Float>):Float { if(v.size<2)return 0f; val mean=v.average().toFloat(); val mx=(v.size-1)/2f; val den=v.indices.sumOf{((it-mx)*(it-mx)).toDouble()}.toFloat().coerceAtLeast(.0001f); return v.indices.sumOf{((it-mx)*(v[it]-mean)).toDouble()}.toFloat()/den }
        val ss=slope(short); val vs=slope(all); val efficiency=abs((all.lastOrNull()?:0f)-(all.firstOrNull()?:0f))/returns.sumOf{abs(it).toDouble()}.toFloat().coerceAtLeast(.0001f); val bodyMean=(src.takeLast(8).map{it.bodyToRangeRatio}.average()).toFloat(); val strength=clamp(abs(ss)*12f+efficiency*.5f)
        val trendClass=when { strength<.18f->"RANGE";ss>.0f&&strength>.72f->"STRONG_BULLISH";ss>.0f&&strength>.38f->"BULLISH";ss>.0f->"WEAK_BULLISH";strength>.72f->"STRONG_BEARISH";strength>.38f->"BEARISH";else->"WEAK_BEARISH" }
        val momentumSigned=src.takeLast(8).mapIndexed{idx,c->signed(c)*c.bodyToRangeRatio*(idx+1)}; val weighted=momentumSigned.sum()/momentumSigned.indices.sumOf{(it+1).toDouble()}.toFloat().coerceAtLeast(1f); val bull=clamp((weighted+1)/2); val bear=clamp((1-weighted)/2); val accel=(src.takeLast(2).sumOf{signed(it).toDouble()}/2.0-(src.take(2).sumOf{signed(it).toDouble()}/max(1,min(2,src.size)))).toFloat(); val exhaustion=clamp((src.takeLast(3).map{it.upperWickLength+it.lowerWickLength}.average()).toFloat()*3f+max(0f,abs(weighted)-.7f)*.8f)
        val recent=src.takeLast(5).map(::range).let{if(it.isEmpty())0f else it.average().toFloat()}; val ratio=recent/median.coerceAtLeast(.0001f); val std=sqrt(src.map{(range(it)-median)*(range(it)-median)}.average().toFloat().coerceAtLeast(0f)); val vclass=when{ratio<.45f->VolatilityClass.VERY_LOW;ratio<.75f->VolatilityClass.LOW;ratio<1.35f->VolatilityClass.NORMAL;ratio<2.2f->VolatilityClass.HIGH;else->VolatilityClass.EXTREME}
        val swings=swings(src); val highs=swings.filter{it.kind=="HIGH"}; val lows=swings.filter{it.kind=="LOW"}; val labels=(highs.zipWithNext().map{if(it.second.value>it.first.value)"HH" else "LH"}+lows.zipWithNext().map{if(it.second.value>it.first.value)"HL" else "LL"}); val bullLabels=labels.count{it=="HH"||it=="HL"}; val bearLabels=labels.count{it=="LH"||it=="LL"}; val bias=if(bullLabels>bearLabels+1)"BULLISH" else if(bearLabels>bullLabels+1)"BEARISH" else "NEUTRAL"; val transition=labels.size>=2&&labels.last()!=labels[labels.lastIndex-1]; val structure=MarketStructure(swings,labels,bias,false,transition,clamp(abs(bullLabels-bearLabels)/max(1,labels.size).toFloat()),"${swings.size} adaptive swings; ${bias.lowercase()} sequence")
        val zones=zones(src); val regime=when{vclass==VolatilityClass.EXTREME->Regime.VOLATILITY_EXPANSION;vclass==VolatilityClass.VERY_LOW->Regime.VOLATILITY_COMPRESSION;transition->Regime.TRANSITION;trendClass.contains("BULL")->Regime.TRENDING_BULL;trendClass.contains("BEAR")->Regime.TRENDING_BEAR;trendClass=="RANGE"->Regime.RANGING;efficiency<.25f->Regime.CHOPPY;else->Regime.TRANSITION}
        return MarketState(structure,zones,MomentumState(bull,bear,clamp(abs(weighted)),clamp((accel+1)/2),exhaustion,clamp(abs(weighted)/(src.sumOf{abs(signed(it)).toDouble()}.toFloat().coerceAtLeast(.0001f)))),VolatilityState(median,std,ratio,clamp((ratio-1)/1.5f),clamp((1-ratio)/.7f),vclass),TrendState(ss,vs,clamp(efficiency),clamp(1f-(returns.map{abs(it)}.let{if(it.size<2)0f else it.average().toFloat()}/returns.map{abs(it)}.average().toFloat().coerceAtLeast(.0001f))),trendClass, strength),regime)
    }

    private fun swings(cs:List<ReconstructedCandle>):List<SwingPoint>{ if(cs.size<3)return emptyList(); val med=cs.map(::range).sorted()[cs.size/2]; val out=mutableListOf<SwingPoint>(); for(i in 1 until cs.lastIndex){val c=cs[i]; val hp=min(c.relativeHigh-cs[i-1].relativeHigh,c.relativeHigh-cs[i+1].relativeHigh); val lp=min(cs[i-1].relativeLow-c.relativeLow,cs[i+1].relativeLow-c.relativeLow); if(hp>med*.35f)out+=SwingPoint(i,c.relativeHigh,"HIGH",hp>=med*.7f,hp); if(lp>med*.35f)out+=SwingPoint(i,c.relativeLow,"LOW",lp>=med*.7f,lp)}; return out}
    private fun zones(cs:List<ReconstructedCandle>):List<SupportResistanceZone>{ if(cs.isEmpty())return emptyList(); val scale=cs.map(::range).sorted()[cs.size/2]*.65f; val cur=cs.last().relativeClose; val clusters=mutableListOf<MutableList<Float>>(); for(v in cs.flatMap{listOf(it.relativeHigh,it.relativeLow)}){val match=clusters.firstOrNull{abs(v-it.average())<=scale.coerceAtLeast(.004f)};if(match!=null)match+=v else clusters+=mutableListOf(v)}; return clusters.map{val center=it.average().toFloat();val kind=if(center<=cur)"SUPPORT" else "RESISTANCE"; SupportResistanceZone(kind,center-scale*.35f,center+scale*.35f,(.12f*it.size+.35f).coerceIn(0f,1f),it.size,abs(cur-center))}.sortedByDescending{it.strength}.take(6)}

    fun vector(candles:List<ReconstructedCandle>, quality:ScreenshotQuality, state:MarketState):FeatureVector { val c=candles.lastOrNull(); val src=if(c?.isComplete==false)candles.dropLast(1) else candles; val tail=src.takeLast(8); val names=listOf("quality_score","blur_score","chart_coverage","candle_visibility","reconstruction_confidence","last_body_ratio","last_upper_wick","last_lower_wick","last_range","last_direction","return_1","return_2","return_3","return_mean","body_mean","range_mean","structure_score","structure_bullish","structure_bearish","bos","choch","short_slope","visible_slope","trend_efficiency","trend_score","momentum_bull","momentum_bear","momentum_strength","momentum_acceleration","exhaustion","directional_efficiency","median_range","range_std","recent_long_ratio","vol_expansion","vol_contraction","is_vol_extreme","is_range","is_trending_bull","is_trending_bear","is_transition","nearest_support_distance","nearest_resistance_distance","support_strength","resistance_strength","doji","hammer","shooting_star","engulfing_bull","engulfing_bear","inside","marubozu","running_present","running_direction","running_body_ratio","running_range","running_confidence"); val returns=tail.zipWithNext().map{it.second.relativeClose-it.first.relativeClose}; val vals=mutableListOf(quality.qualityScore,quality.blurScore,quality.chartCoverage,quality.candleVisibility,candles.map{it.visualConfidence}.average().toFloat()); vals+=listOf(c?.bodyToRangeRatio?:0f,c?.upperWickLength?:0f,c?.lowerWickLength?:0f,c?.totalRange?:0f,c?.let(::signed)?:0f); vals+=listOf(returns.getOrNull(returns.lastIndex)?:0f,returns.getOrNull(returns.lastIndex-1)?:0f,returns.getOrNull(returns.lastIndex-2)?:0f,returns.averageOrZero(),tail.map{it.bodyHeight}.averageOrZero(),tail.map{it.totalRange}.averageOrZero()); vals+=listOf(state.structure.score,if(state.structure.bias=="BULLISH")1f else 0f,if(state.structure.bias=="BEARISH")1f else 0f,if(state.structure.breakOfStructure)1f else 0f,if(state.structure.changeOfCharacter)1f else 0f); vals+=listOf(state.trend.shortSlope,state.trend.visibleSlope,state.trend.efficiency,state.trend.score,state.momentum.bullishScore,state.momentum.bearishScore,state.momentum.strength,state.momentum.acceleration,state.momentum.exhaustionProbability,state.momentum.efficiency); vals+=listOf(state.volatility.medianRange,state.volatility.rangeStd,state.volatility.recentLongRatio,state.volatility.expansion,state.volatility.contraction,if(state.volatility.classification==VolatilityClass.EXTREME)1f else 0f,if(state.regime==Regime.RANGING)1f else 0f,if(state.regime==Regime.TRENDING_BULL)1f else 0f,if(state.regime==Regime.TRENDING_BEAR)1f else 0f,if(state.regime==Regime.TRANSITION)1f else 0f); val sup=state.zones.filter{it.kind=="SUPPORT"};val res=state.zones.filter{it.kind=="RESISTANCE"};vals+=listOf(sup.minOfOrNull{it.distanceFromCurrent}?:1f,res.minOfOrNull{it.distanceFromCurrent}?:1f,sup.maxOfOrNull{it.strength}?:0f,res.maxOfOrNull{it.strength}?:0f); val previous=src.getOrNull(src.lastIndex-1); val doji=if((c?.bodyToRangeRatio?:1f)<=.18f)1f else 0f; val hammer=if(c!=null&&c.lowerWickLength>c.bodyHeight*1.8f&&c.upperWickLength<c.bodyHeight)1f else 0f; val star=if(c!=null&&c.upperWickLength>c.bodyHeight*1.8f&&c.lowerWickLength<c.bodyHeight)1f else 0f; val bullEngulf=if(c!=null&&previous!=null&&c.direction==Direction.UP&&previous.direction==Direction.DOWN&&c.bodyHeight>previous.bodyHeight*1.05f)1f else 0f; val bearEngulf=if(c!=null&&previous!=null&&c.direction==Direction.DOWN&&previous.direction==Direction.UP&&c.bodyHeight>previous.bodyHeight*1.05f)1f else 0f; val inside=if(c!=null&&previous!=null&&c.relativeHigh<=previous.relativeHigh&&c.relativeLow>=previous.relativeLow)1f else 0f; val marubozu=if((c?.bodyToRangeRatio?:0f)>.82f)1f else 0f; vals+=listOf(doji,hammer,star,bullEngulf,bearEngulf,inside,marubozu); vals+=listOf(if(c?.isComplete==false)1f else 0f,c?.let(::signed)?:0f,c?.bodyToRangeRatio?:0f,c?.totalRange?:0f,if(c?.isComplete==false)c.visualConfidence else 0f); val safe=vals.map{if(it.isFinite())it else 0f}.toFloatArray(); return FeatureVector(safe,names,FEATURE_SCHEMA_VERSION,BooleanArray(safe.size){true},mapOf("running_candle_excluded_from_target" to "true")) }
    private fun List<Float>.averageOrZero()=if(isEmpty())0f else average().toFloat()
}
